const FLOW_TOPICS = {
  opportunities:{label:'기회가 되는 흐름',field:'chance',navGroup:'시기의 흐름',title:'기회가 될 장면을 구체적으로 살펴요'},
  cautions:{label:'조심할 점',field:'care',navGroup:'관계와 생활',title:'같은 성향에서도 놓치기 쉬운 조건이 있어요'},
  response:{label:'어떻게 행동하고 대처할까',field:'response',navGroup:'관계와 생활',title:'지금 할 수 있는 한 단계로 바꿔 봐요'},
};
const FLOW_FOLLOW_UPS={
  opportunities:'작게 시도한 뒤에는 기대했던 점과 직접 확인한 점을 나누어 보세요. 새로운 사람을 알게 된 것, 실제 작업이 진행된 것, 아직 준비가 필요한 것은 서로 다른 결과예요. 해 본 내용에 맞춰 다음 범위를 정하면 좋은 느낌만으로 약속이 늘어나는 것을 줄이기 좋아요.',
  cautions:'마음이 급해지는 장면이 있다면 실제로 바뀐 조건이 무엇인지 한 가지부터 적어 보세요. 대답을 서둘러 달라는 요청과 지금 결정하지 않으면 달라지는 일이 같은지 확인하는 거예요. 무엇을 모르는지 말할 수 있으면 필요한 질문도 구체적으로 정할 수 있어요.',
  response:'한 가지를 해 본 뒤에는 문제가 완전히 사라졌는지만 보지 말고, 전보다 말하기 쉬워졌는지와 내 부담이 줄었는지도 살펴보세요. 도움이 됐다면 그 방법을 이어 가고, 여전히 막힌다면 시간·역할·도움 중 무엇을 바꿔야 할지 하나씩 고르면 돼요.',
};
function flowCard(registry,profile,key,{transit=null,prefix='natal',monthly=false}={}) {
  const config=FLOW_TOPICS[key];
  const codes=transit?unique([transit.stemGod.code,transit.branchGod.code]):selectNatalCodes(profile,'work',key==='cautions'?['authority','peer','wealth','expression','resource']:null);
  const domain=key==='cautions'?'money':'work',natalCodes=transit?selectNatalCodes(profile,domain):codes;
  const interactions=transit?transit.interactions:profile.interactions;
  const relation=domainInteraction(interactions,prefix,domain);
  const situation=buildReaderSituation({topic:key,codes,natalCodes,interactions,periodLabel:transit?(monthly?'이번 달':'이 해'):'평소'});
  const [opening,natal,condition,boundary,example,action]=situation.paragraphs;
  const result=card(registry,{id:`${prefix.replaceAll('.','-')}-${key}`,label:config.label,title:situation.title,navGroup:config.navGroup,codes,natalCodes,
    ...detailContent([
      [transit?'이번 시기에 먼저 살필 일':'평소 이런 장면을 살펴보세요',[opening]],
      ['내 성향과 연결해서 보면',[natal]],
      ['잘 풀리려면 필요한 조건',[condition]],
      ['무리하지 않기 위해 볼 부분',[boundary]],
      ['생활 속 가상 장면',[example]],
      ['해 본 뒤 다시 살필 점',[FLOW_FOLLOW_UPS[key]]],
      ['지금 해 볼 한 단계',[action]],
    ]),
    factIds:['natal.day-master','natal.scope',...natalFacts(profile,codes),
      ...(transit?[`${prefix}.period`,...profile.gods.map(natalId),...transitFacts(transit,prefix,codes)]:[]),...(relation?.factIds||[])],
    chapterId:transit?(monthly?'month-interactions':'annual-interactions'):'natal-combined-themes'});
  return {...result,situationRuleIds:situation.ruleIds};
}
function lifelongOverview(report,fortune,registry) {
  const profile=fortune.profile,voice=STEM_VOICES[profile.dayMaster.hanja];
  const season=seasonMeaning(report);
  const cards=[characterCard(registry,profile,season),aptitudeCard(registry,profile),pathCard(registry,profile,season),
    domainCard(registry,profile,'relationships'),lifeLensCard(registry,profile,'parents'),lifeLensCard(registry,profile,'children'),
    domainCard(registry,profile,'work'),careerCard(registry,profile),domainCard(registry,profile,'learning'),
    domainCard(registry,profile,'money'),lifeLensCard(registry,profile,'contracts'),
    lifeLensCard(registry,profile,'helpers'),lifeLensCard(registry,profile,'boundaries'),lifeLensCard(registry,profile,'health'),
    lifeLensCard(registry,profile,'space'),lifeLensCard(registry,profile,'safety'),
    flowCard(registry,profile,'cautions'),flowCard(registry,profile,'response')];
  const relation=interactionReading(profile.interactions,'natal');
  const work=selectNatalCodes(profile,'work')[0],money=selectNatalCodes(profile,'money')[0];
  const paragraphs=[`일에서는 ${particle(DAILY_VOICES[work].work.thread,'을','를')} 중요하게 여기고, 돈에서는 ${particle(DAILY_VOICES[money].money.thread,'을','를')} 살피는 모습이에요.`,season?.reading,relation?.reading].filter(Boolean);
  return {title:'타고난 운 · 나의 바탕',headline:voice.headline,
    ...detailContent([['일과 돈에서 보이는 내 모습',[paragraphs[0]]],['생활과 관계에서 함께 살필 점',paragraphs.slice(1)]]),cards,origin:ORIGIN,
    factIds:checkedFacts(registry,['natal.day-master','natal.scope',...(season?.factIds||[]),...cards.flatMap(value=>value.factIds),...(relation?.factIds||[])])};
}
function periodOverview(profile,transit,registry,{year,month=null}) {
  const monthly=month!==null,prefix=monthly?`month.${month}`:'annual';
  const label=monthly?`${month}월`:`${year}년`;
  const codes=unique([transit.stemGod.code,transit.branchGod.code]);
  const connection=personalPeriodParts(profile,codes,'work',label);
  const headline=`${PERSONAL_CONCLUSIONS[connection.natalCodes[0]].address}, ${label}에는 `+(codes.length===1?PERIOD_HEADLINES[codes[0]].last
    :`${PERIOD_HEADLINES[codes[0]].first} ${PERIOD_HEADLINES[codes[1]].last}`)+' 일을 먼저 챙겨 보세요.';
  const paragraphs=[connection.conclusion,`${connection.focus} ${connection.application}`];
  const relation=interactionReading(transit.interactions,prefix);
  if(relation)paragraphs.push(relation.reading);
  const context={transit,prefix,monthly};
  const cards=[...Object.keys(DOMAINS).map(domain=>domainCard(registry,profile,domain,context)),
    ...Object.keys(FLOW_TOPICS).map(key=>flowCard(registry,profile,key,context))];
  return {title:`${label} ${monthly?'월별운':'올해운'} 핵심`,headline,
    ...detailContent([['평소 내 모습',[paragraphs[0]]],['이번 시기에 적용해 보기',[paragraphs[1]]],['주변과 맞춰 갈 부분',paragraphs.slice(2)]]),cards,origin:ORIGIN,
    ...(monthly?{month}:{year}),godCodes:codes,
    factIds:checkedFacts(registry,['natal.day-master','natal.scope',`${prefix}.pillar`,`${prefix}.period`,
      ...profile.gods.map(natalId),...transitFacts(transit,prefix,codes),...cards.flatMap(value=>value.factIds),...(relation?.factIds||[])])};
}

function scopeNotice(chart) {
  const uncertain=chart.pillars.filter(pillar=>pillar.uncertain||!pillar.hanja);
  if(!uncertain.length)return '';
  if(uncertain.some(pillar=>pillar.key!=='hour'))return '태어난 시각에 따라 달라질 수 있는 부분은 빼고, 확인된 내용만 읽었어요.';
  return '태어난 시간을 몰라 그 부분은 빼고, 확인된 내용만 읽었어요.';
}

export function attachReaderSummary(report,chart,fortune) {
  if(!Array.isArray(report?.facts)||!fortune?.profile?.dayMaster||chart?.dayMaster?.hanja!==fortune.profile.dayMaster.hanja
    ||!STEM_VOICES[fortune.profile.dayMaster.hanja]||!Array.isArray(fortune.months)||fortune.months.length!==12
    ||new Set(fortune.months.map(value=>value.month)).size!==12)throw new Error('확인된 사주로 핵심 풀이를 다시 준비해 주세요.');
  const registry=new Set(report.facts.map(value=>value.id));
  const allGods=[...fortune.profile.gods.map(entry=>entry.god),fortune.annual.stemGod,fortune.annual.branchGod,
    ...fortune.months.flatMap(value=>[value.stemGod,value.branchGod])];
  if(allGods.some(god=>!GOD_VOICES[god?.code]||!GOD_CONTEXTS[god.code]))throw new Error('핵심 풀이의 관계를 확인하지 못했어요.');
  report.reader={
    scopeNotice:scopeNotice(chart),
    lifelong:lifelongOverview(report,fortune,registry),
    annual:periodOverview(fortune.profile,fortune.annual,registry,{year:fortune.year}),
    months:[...fortune.months].sort((a,b)=>a.month-b.month).map(transit=>periodOverview(fortune.profile,transit,registry,{year:fortune.year,month:transit.month})),
  };
  return report;
}
